import {api,publicBoot,isDemo,setSession,clearCache,Demo,demoRole} from './api.js';
import {downloadXlsx} from './xlsx.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const state={user:null,public:null,member:null,admin:null,course:null,page:0,filter:'all',search:'',report:null,reportFilter:{},reportKind:'sales',settings:null,crmBoard:false,epoch:0};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(x)||0);
const date=x=>x?new Date(x).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'}):'—';
const truth=x=>x===true||String(x)==='true';
const icon=(name)=>{const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',catalog:'M3 7l9-4 9 4-9 4z M6 10v7l6 4 6-4v-7',courses:'M3 5h7l2 2h9v14H3z',transactions:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 8h6 M9 12h6',notifications:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 21h4',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M9 12a3 3 0 1 0 6 0a3 3 0 1 0-6 0',crm:'M16 21v-3a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v3 M9.5 10a4 4 0 1 0 0-8a4 4 0 1 0 0 8 M19 8v6 M16 11h6',reports:'M4 20V10h4v10 M10 20V4h4v16 M16 20V7h4v13',members:'M16 21v-3a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8a4 4 0 1 0 0 8 M18 3a4 4 0 0 1 0 8 M18 14a4 4 0 0 1 4 4v3'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.dashboard}"/></svg>`;};
const btn=(label,action,attrs='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,to,cls='btn')=>`<a class="${cls}" href="#${to}">${label}</a>`;
const statuses={Paid:['Lunas','green'],Verified:['Terverifikasi','green'],Active:['Aktif','green'],Published:['Terbit','green'],Pending:['Menunggu Bayar','amber'],AwaitingReview:['Menunggu Review','amber'],AwaitingPayment:['Menunggu Bayar','amber'],Rejected:['Ditolak','red'],Failed:['Gagal','red'],Blocked:['Diblokir','red'],Uncertain:['Perlu Diperiksa','amber'],Queued:['Dalam Antrean','blue'],Submitted:['Diterima Provider','blue'],Sent:['Terkirim','green'],Draft:['Draf',''],Archived:['Arsip',''],Expired:['Kedaluwarsa',''],Refunded:['Dikembalikan',''],Cancelled:['Dibatalkan',''],Retry:['Menunggu Ulang','amber']};
const badge=s=>{const [label,color]=statuses[s]||[s||'—',''];return `<span class="tag ${color}">${esc(label)}</span>`;};
const empty=(title,text,to,label='Jelajahi Kelas')=>`<div class="empty"><div class="empty-symbol">▱</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${to?link(label,to):''}</div>`;
const head=(title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">BELAJAR · BERTUMBUH · BERKARYA</div><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div>${actions||`<span class="date-label">${date(new Date())}</span>`}</div>`;
const field=(name,label,value='',type='text',opts='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${opts}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${opts}>`}</div>`;
const select=(name,label,options,value)=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" class="full">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
const check=(name,label,value)=>`<div class="field"><label class="check"><input type="checkbox" name="${name}" ${truth(value)?'checked':''}>${esc(label)}</label></div>`;
const form=(name,content,hidden='',submit='Simpan')=>`<form data-form="${name}">${hidden}${content}<p class="form-status error-text" role="alert"></p><div class="form-actions"><button type="submit" class="btn">${submit}</button></div></form>`;
const hidden=(name,value)=>`<input type="hidden" name="${name}" value="${esc(value)}">`;
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.classList.toggle('error',error);t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',5000);}
function showModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!modal.open)modal.showModal();}
function applyTheme(value){localStorage.setItem('pkd:theme',value);$('#theme').value=value;document.documentElement.dataset.theme=value==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):value;}
applyTheme(localStorage.getItem('pkd:theme')||'system');$('#theme').addEventListener('change',e=>{const theme=e.target.value;applyTheme(theme);if(state.user){state.user.theme=theme;api('profile.save',{...state.user,theme}).catch(()=>toast('Tema tersimpan di perangkat. Sinkronisasi akun belum berhasil.',true));}});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>applyTheme(localStorage.getItem('pkd:theme')||'system'));
function nav(){const member=[['dashboard','Dashboard','dashboard'],['catalog','Katalog Kelas','catalog'],['courses','Kelas Saya','courses'],['transactions','Transaksi','transactions'],['notifications','Notifikasi','notifications'],['profile','Pengaturan','settings']];const admin=[['admin','Ringkasan Bisnis','dashboard'],['editor','Kelas & Materi','courses'],['members','Member','members'],['payments','Pembayaran','transactions'],['crm','CRM Kontak','crm'],['messages','WA & Email','notifications'],['reports','Laporan','reports'],['settings','Pengaturan Admin','settings']];let html=member.map(([route,label,i])=>`<a class="nav-item" href="#${route}" data-nav="${route}">${icon(i)}<span>${label}</span></a>`).join('');if(state.user?.role==='Admin')html+=`<div class="nav-section">WORKSPACE ADMIN</div>`+admin.map(([route,label,i])=>`<a class="nav-item" href="#${route}" data-nav="${route}">${icon(i)}<span>${label}</span></a>`).join('');$('#navigation').innerHTML=html;$('#user-name').textContent=state.user?.name||'Pengunjung';$('#user-role').textContent=state.user?.role==='Admin'?'Owner / Admin':state.user?'Member Aktif':'Masuk untuk belajar';$('.account .avatar').textContent=(state.user?.name||'KD').split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase();$('#signout').hidden=!state.user;}
const adminRoutes=new Set(['admin','editor','members','payments','crm','messages','reports','settings']);
let routeToken=0;
async function route(){window.scrollTo(0,0);const renderStart=performance.now();const token=++routeToken;const [page='dashboard',id,lessonId]=location.hash.slice(1).split('/');state.routeId=id;$('#sidebar').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('#crumb').textContent=({dashboard:'Dashboard',catalog:'Katalog Kelas',courses:'Kelas Saya',course:'Detail Kelas',learn:'Ruang Belajar',checkout:'Checkout',order:'Detail Transaksi',transactions:'Transaksi',notifications:'Notifikasi',profile:'Profil',login:'Masuk',admin:'Ringkasan Bisnis',editor:'Kelas & Materi',members:'Member',payments:'Pembayaran',crm:'CRM',messages:'WA & Email',reports:'Laporan',settings:'Pengaturan Admin'})[page]||'Portal';
 if(adminRoutes.has(page)&&state.user?.role!=='Admin'){main.innerHTML=empty('Akses khusus admin','Masuk dengan akun pengelola.','login','Masuk');return;}
 if(!state.user&&!['catalog','course','learn','login'].includes(page)){renderLogin();return;}
 // Kerangka halaman langsung muncul; respons rute lama tidak menimpa halaman baru.
 main.innerHTML=head($('#crumb').textContent,'Menyiapkan ruang belajarmu…')+'<div class="skeleton title"></div><div class="skeleton"></div><div class="skeleton"></div>';
 try{
 if(adminRoutes.has(page)&&!state.admin){state.admin=await api('admin.boot',{page:state.page});if(token!==routeToken)return;}
 switch(page){
 case 'dashboard':renderDashboard();break;case 'courses':renderCourses();break;case 'catalog':renderCatalog();break;case 'login':renderLogin();break;
 case 'course':case 'learn':case 'checkout':{const detail=await api(state.user?'course.read':'course.public',{course_id:id});if(token!==routeToken)return;state.course=detail;if(page==='learn')renderLesson(lessonId);else if(page==='checkout')renderCheckout();else renderCourse();break;}
 case 'order':renderOrder(id);break;case 'transactions':renderTransactions();break;case 'notifications':renderNotifications();break;case 'profile':renderProfile();break;
 case 'admin':state.report=await api('admin.reports',{});if(token!==routeToken)return;renderAdmin();break;
 case 'editor':renderEditor();break;case 'members':renderMembers();break;case 'payments':renderPayments();break;case 'crm':renderCRM();break;case 'messages':renderMessages();break;
 case 'reports':state.report=await api('admin.reports',state.reportFilter);if(token!==routeToken)return;renderReports();break;
 case 'settings':state.settings=await api('admin.settings.read');if(token!==routeToken)return;renderSettings();break;
 default:main.innerHTML=empty('Halaman tidak ditemukan','Pilih menu untuk melanjutkan.','dashboard','Kembali ke Dashboard');
 }
 }catch(e){if(token!==routeToken)return;main.innerHTML=head('Belum dapat memuat halaman','Data Anda tidak diubah.')+empty('Koneksi perlu diperiksa',e.message)+btn('Coba Lagi','retry');}
 if(token===routeToken){main.dataset.renderMs=(performance.now()-renderStart).toFixed(1);main.focus({preventScroll:true});}
}
async function refreshMember(){state.member=await api('member.boot',{}, {fresh:true});state.user=state.member.user;nav();}
async function refreshAdmin(){state.admin=await api('admin.boot',{page:state.page},{fresh:true});}
function courseProgress(cid){const details=state.course?.course.course_id===cid?state.course:null;const completed=(state.member?.progress||[]).filter(p=>truth(p.completed)&&(details?details.lessons.some(l=>l.lesson_id===p.lesson_id):p.lesson_id.startsWith(cid)));const total=details?details.lessons.filter(l=>truth(l.is_required)).length:0;return {done:completed.length,total,pct:total?Math.round(completed.length/total*100):null};}
// Dashboard memakai ringkasan server bila tersedia; tidak menebak total pelajaran untuk ID produksi.
function summary(c){return state.member?.course_summaries?.[c.course_id]||courseProgress(c.course_id);}
function ownedCourses(){return(state.member?.courses||[]).filter(c=>state.member.enrollments.some(e=>e.course_id===c.course_id&&e.status==='Active'&&(!e.expires_at||Date.parse(e.expires_at)>Date.now())));}
function courseCard(c,catalog=false){const p=summary(c);return `<article class="course-card ${catalog?'catalog-card':''}"><a href="#course/${esc(c.course_id)}" class="cover"><img src="./assets/${['code','marketing','design','business'].includes(c.cover)?c.cover:'code'}.svg" alt="Ilustrasi kelas ${esc(c.category)}"></a><div class="course-body"><span class="course-category">${esc(c.category||'Kelas Digital')}</span><h3><a href="#course/${esc(c.course_id)}" style="color:inherit">${esc(c.title)}</a></h3><div class="course-meta"><span>▱ Materi terstruktur</span><span class="duration">◷ Belajar mandiri</span></div>${catalog?`<p class="subtitle">${esc(c.description).slice(0,100)}…</p><div class="price-row"><span class="price">${money(c.price_idr)}</span>${link('Lihat Kelas ↗','course/'+c.course_id,'btn small secondary')}</div>`:`<div class="progress-info"><span>${p.total?`${p.done} dari ${p.total} pelajaran`:p.done+' pelajaran selesai'}</span><b>${p.pct!==null?p.pct+'%':'Mulai / lanjutkan'}</b></div><div class="progress-line"><i style="width:${p.pct||0}%"></i></div>`}</div>${catalog?'':link('→','learn/'+c.course_id,'round-arrow')}</article>`;}
function calendar(){const d=new Date(),y=d.getFullYear(),m=d.getMonth(),today=d.getDate(),first=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate();return `<div class="calendar-head"><span>${d.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</span><span>◷</span></div><div class="calendar">${['S','S','R','K','J','S','M'].map(s=>`<span class="day">${s}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:count},(_,i)=>`<span class="${i+1===today?'today':''}">${i+1}</span>`).join('')}</div><p class="calendar-note">Belajar mandiri sesuai waktumu.<br>Belum ada jadwal kegiatan tambahan.</p>`;}
function renderDashboard(){const courses=ownedCourses(),done=(state.member.progress||[]).filter(p=>truth(p.completed)).length;const all=courses.map(summary),total=all.reduce((s,p)=>s+(p.total||0),0),activeDone=all.reduce((s,p)=>s+p.done,0),pct=total?Math.round(activeDone/total*100):0;main.innerHTML=head('Selamat datang, '+(state.user.name.split(' ')[0])+' 👋','Setiap pelajaran adalah langkah menuju peluang baru.')+`<div class="dashboard-grid"><div><section class="welcome"><div class="welcome-copy"><div class="eyebrow">INVESTASI TERBAIK ADALAH DIRIMU</div><h2>Ide hebat dimulai<br>dari kemauan belajar.</h2><p>Lanjutkan perjalananmu dan wujudkan produk digital pertamamu, satu langkah demi langkah.</p>${link(courses.length?'Lanjutkan Belajar  →':'Temukan Kelas  →',courses.length?'learn/'+courses[0].course_id:'catalog')}</div><img src="./assets/welcome.svg" alt="Ilustrasi meja belajar digital"></section><div class="section-head"><h2>Kelas yang Sedang Dipelajari <span class="tag">${courses.length}</span></h2><a href="#courses">Lihat semua ↗</a></div><div class="filters" style="margin-bottom:17px">${['Semua Kelas','Dalam Proses','Selesai'].map((s,i)=>`<button class="chip ${state.filter===['all','progress','done'][i]?'active':''}" data-action="course-filter" data-value="${['all','progress','done'][i]}">${s}</button>`).join('')}</div><div class="course-list">${courses.filter(c=>state.filter==='all'||(state.filter==='done'?summary(c).pct===100:summary(c).pct!==100)).map(c=>courseCard(c)).join('')||empty('Mulai perjalanan belajarmu','Pilih kelas yang sesuai dengan tujuanmu.','catalog')}</div><div class="section-head gap"><h2>Pilihan untuk Langkah Berikutnya</h2><a href="#catalog">Jelajahi katalog ↗</a></div><p class="subtitle">Temukan keterampilan baru yang melengkapi perjalananmu.</p></div><aside class="right-rail"><section class="panel"><div class="panel-head"><h2>Progres Belajarmu</h2><span class="muted">⋯</span></div><div class="ring-wrap"><svg class="ring" viewBox="0 0 118 118" aria-hidden="true"><circle cx="59" cy="59" r="49"/><circle cx="59" cy="59" r="49" stroke-dasharray="${pct*3.079} 308"/></svg><div class="ring-text"><strong>${pct}%</strong><small>terus bertumbuh</small></div></div><div class="stats-split"><span><strong>${courses.length}</strong>Kelas aktif</span><span><strong>${done}</strong>Pelajaran selesai</span></div></section><section class="panel">${calendar()}</section><section class="panel"><div class="panel-head"><h2>Info untuk Kamu</h2><a href="#notifications">Semua ↗</a></div>${state.member.notifications.slice(0,2).map(n=>`<div class="notice"><div class="notice-icon">✧</div><div><strong>${esc(n.title)}</strong><p>${esc(n.body).slice(0,100)}</p></div></div>`).join('')||'<p class="subtitle">Belum ada pengumuman baru.</p>'}</section><section class="panel quote"><span class="badge-label">PENGINGAT KECIL</span><p class="gap">“Tidak perlu langsung mahir.<br>Cukup mulai, lalu terus belajar.”</p></section></aside></div>`;}
function renderCourses(){main.innerHTML=head('Kelas Saya','Semua perjalanan belajarmu, dalam satu tempat.')+`<div class="course-list">${ownedCourses().map(c=>courseCard(c)).join('')||empty('Belum memiliki kelas','Temukan kelas pertama untuk memulai.','catalog')}</div>`;}
function renderCatalog(){main.innerHTML=head('Skill Baru, Peluang Baru','Kelas praktis untuk mengembangkan ide menjadi karya digital.')+`<div class="toolbar"><input id="course-search" type="search" placeholder="Cari kelas atau topik…" value="${esc(state.search)}" aria-label="Cari kelas"><span class="tag">Belajar mandiri · Materi terstruktur</span></div><div class="grid" id="catalog-grid"></div>`;paintCatalog();}
function paintCatalog(){if(!$('#catalog-grid'))return;const data=(state.public?.courses||[]).filter(c=>(c.title+' '+c.category).toLowerCase().includes(state.search.toLowerCase()));$('#catalog-grid').innerHTML=data.map(c=>courseCard(c,true)).join('')||empty('Kelas belum ditemukan','Coba kata kunci lain.');}
function curriculum(detail,learn=false,current=''){return detail.modules.map(m=>`<details class="module" open><summary>${esc(m.title)}</summary>${detail.lessons.filter(l=>l.module_id===m.module_id).map(l=>{const complete=detail.progress.some(p=>p.lesson_id===l.lesson_id&&truth(p.completed));return `<a class="lesson-row ${l.lesson_id===current?'active':''}" href="#${l.locked?(detail.access?'course/':'checkout/')+detail.course.course_id:'learn/'+detail.course.course_id+'/'+l.lesson_id}"><span>${complete?'✓':l.locked?'▣':'▷'} &nbsp;${esc(l.title)}</span><small>${l.locked?(detail.access?'Selesaikan sebelumnya':'Terkunci'):truth(l.is_preview)?'Pratinjau':complete?'Selesai':''}</small></a>`;}).join('')||'<p class="hint" style="padding:15px">Pelajaran akan ditambahkan.</p>'}</details>`).join('')||empty('Kurikulum sedang disiapkan','Hubungi admin untuk informasi kelas.');}
function renderCourse(){const d=state.course,c=d.course;main.innerHTML=head(c.title,c.category||'Kelas Digital')+`<div class="two-col"><div class="stack"><div class="detail-cover"><img src="./assets/${esc(c.cover||'code')}.svg" alt="Ilustrasi kelas"></div><section class="panel"><h2>Tentang Kelas Ini</h2><p class="body-copy">${esc(c.description)}</p><ul class="info-list"><li>Ikuti panduan awal dan pelajari modul secara berurutan.</li><li>Belajar mandiri sesuai kecepatanmu.</li><li>Materi pendukung tersedia pada pelajaran terkait.</li></ul></section><section><h2>Jalur Belajarmu</h2>${curriculum(d)}</section></div><aside class="stack"><section class="panel"><span class="course-category">MULAI LANGKAH BERIKUTNYA</span><h2>${esc(c.title)}</h2><p class="price">${money(c.price_idr)}</p><p class="subtitle">${Number(c.access_days)>0?'Akses '+c.access_days+' hari':'Tanpa tanggal kedaluwarsa'}</p><div class="gap">${link(d.access?'Lanjutkan Belajar →':'Beli Kelas →',d.access?'learn/'+c.course_id:'checkout/'+c.course_id,'btn block')}</div><ul class="info-list"><li>Video series dan kurikulum terstruktur</li><li>Dokumen, ZIP, dan tautan pendukung</li><li>Progres belajar tersimpan</li></ul></section><section class="panel"><h3>Kebijakan Pembelian</h3><p class="subtitle">${esc(state.public.refund_policy||'Hubungi admin untuk informasi.')}</p></section></aside></div>`;}
function youtube(url){try{const u=new URL(url);if(u.hostname==='youtu.be')return u.pathname.slice(1).split('/')[0];if(['youtube.com','www.youtube.com'].includes(u.hostname))return u.searchParams.get('v')||u.pathname.split('/').filter(Boolean)[1];}catch{}return '';}
function renderLesson(requested){const d=state.course;const last=state.member?.progress.filter(p=>d.lessons.some(l=>l.lesson_id===p.lesson_id)).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0];const l=d.lessons.find(l=>l.lesson_id===requested)||d.lessons.find(l=>l.lesson_id===last?.lesson_id)||d.lessons.find(l=>!l.locked);if(!l){main.innerHTML=head(d.course.title,'Ruang belajar')+empty('Belum ada pelajaran yang dapat dibuka','Beli kelas atau hubungi admin.','course/'+d.course.course_id,'Lihat Kelas');return;}if(l.locked){main.innerHTML=empty(d.access?'Selesaikan Pelajaran Sebelumnya':'Pelajaran khusus member',d.access?'Ikuti urutan pada kurikulum untuk membuka pelajaran ini.':'Beli kelas untuk membuka seluruh materi.',(d.access?'course/':'checkout/')+d.course.course_id,d.access?'Lihat Kurikulum':'Beli Kelas');return;}const video=youtube(l.video_url),i=d.lessons.findIndex(x=>x.lesson_id===l.lesson_id),complete=d.progress.some(p=>p.lesson_id===l.lesson_id&&truth(p.completed));main.innerHTML=head(l.title,d.course.title)+`<div class="two-col"><div class="stack"><div class="video">${video&&/^[\w-]{11}$/.test(video)?`<iframe src="https://www.youtube-nocookie.com/embed/${video}" title="${esc(l.title)}" allow="encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>`:`<p>▷<br>${isDemo?'Video simulasi belum diisi. Tambahkan tautan YouTube melalui Editor Kelas.':'Video belum tersedia. Pelajari deskripsi dan materi pendukung atau hubungi admin.'}</p>`}</div><section class="panel"><div class="section-head"><h2>Tentang Pelajaran</h2>${complete?'<span class="tag green">✓ Selesai</span>':''}</div><p class="body-copy">${esc(l.description)}</p>${d.access?btn(complete?'✓ Selesai · Tandai Belum Selesai':'Tandai Selesai ✓','complete',`data-id="${esc(l.lesson_id)}" data-value="${!complete}"`):link('Buka Seluruh Kelas','checkout/'+d.course.course_id)}<div class="form-actions">${i>0?link('← Sebelumnya','learn/'+d.course.course_id+'/'+d.lessons[i-1].lesson_id,'btn secondary'):''}${i<d.lessons.length-1?link('Berikutnya →','learn/'+d.course.course_id+'/'+d.lessons[i+1].lesson_id,'btn secondary'):''}</div></section><section class="panel"><h2>Materi Pendukung</h2>${d.materials.filter(m=>m.lesson_id===l.lesson_id).map(m=>`<div class="resource"><div><strong>${esc(m.title)}</strong><div class="hint">${esc(m.type==='link'?'Tautan eksternal':m.mime_type||'Berkas')} ${m.size_bytes?'· '+Math.ceil(Number(m.size_bytes)/1024)+' KB':''}</div></div>${btn(m.type==='link'?'Buka ↗':'Unduh ↓','resource',`data-id="${esc(m.material_id)}"`,'small secondary')}</div>`).join('')||'<p class="subtitle">Belum ada materi tambahan untuk pelajaran ini.</p>'}</section></div><aside><h2>Kurikulum Kelas</h2>${curriculum(d,true,l.lesson_id)}</aside></div>`;}
function renderCheckout(){const c=state.course.course;if(state.course.access){main.innerHTML=empty('Kelas sudah dapat diakses','Lanjutkan perjalanan belajarmu.','learn/'+c.course_id,'Mulai Belajar');return;}main.innerHTML=head('Satu Langkah Menuju Skill Baru','Pilih metode pembayaran yang nyaman untukmu.')+`<div class="two-col"><section class="panel"><h2>Metode Pembayaran</h2>${form('checkout',`<label class="payment-option"><input type="radio" name="method" value="manual" checked><span><strong>Transfer / QRIS Manual</strong><small>Bukti diperiksa oleh admin sebelum akses aktif.</small></span></label><label class="payment-option"><input type="radio" name="method" value="gateway" ${state.public.gateway_enabled?'':'disabled'}><span><strong>Payment Gateway</strong><small>${state.public.gateway_enabled?'Status diverifikasi otomatis melalui gateway.':'Belum diaktifkan oleh admin.'}</small></span></label><p class="hint">Dengan melanjutkan, Anda menyetujui kebijakan akses dan pembelian kelas ini.</p>`,hidden('course_id',c.course_id),'Buat Pesanan →')}</section><aside class="panel"><h2>Ringkasan Pesanan</h2><div class="cover" style="width:100%;height:160px;margin-bottom:18px"><img src="./assets/${esc(c.cover)}.svg" alt="Ilustrasi kelas"></div><h3>${esc(c.title)}</h3><p class="subtitle">${Number(c.access_days)>0?'Akses '+c.access_days+' hari':'Akses tanpa tanggal kedaluwarsa'}</p><div class="order-total"><span>Total Pembayaran</span><span>${money(c.price_idr)}</span></div><p class="hint">${esc(state.public.refund_policy)}</p></aside></div>`;}
function orderPayments(o){return(state.member?.payments||[]).find(p=>p.order_id===o.order_id);}
function renderOrder(id){const o=state.member?.orders.find(o=>o.order_id===id);if(!o){main.innerHTML=empty('Pesanan tidak ditemukan','Segarkan transaksi atau masuk dengan akun pemesan.','transactions','Lihat Transaksi');return;}const p=orderPayments(o);main.innerHTML=head('Detail Pesanan','Pantau pembayaran dan akses kelas Anda.')+`<div class="two-col"><section class="panel"><div class="align-center"><div class="success-mark ${o.status==='Paid'?'':'pending-mark'}">${o.status==='Paid'?'✓':'◷'}</div><h2>${o.status==='Paid'?'Pembayaran Terverifikasi':'Status Pembayaran'}</h2>${badge(o.status)} ${p?badge(p.status):''}</div><div class="status-row gap"><span>Kelas</span><strong>${esc(o.title_snapshot)}</strong></div><div class="status-row"><span>Total</span><strong>${money(o.total_idr)}</strong></div><div class="status-row"><span>Nomor Pesanan</span><small>${esc(o.order_id)}</small></div><div class="status-row"><span>Batas Pembayaran</span><small>${date(o.expires_at)}</small></div>${p?.reason?`<div class="inline-notice gap">${esc(p.reason)}</div>`:''}<div class="form-actions">${btn('Periksa Status','refresh-payment',`data-id="${esc(o.order_id)}"`,'secondary')}${o.status==='Paid'?link('Mulai Belajar →','learn/'+o.course_id):''}</div></section><aside class="panel"><h2>${o.method==='manual'?'Petunjuk Pembayaran':'Pembayaran Gateway'}</h2>${o.status==='Pending'?(o.method==='manual'?`<p class="body-copy">${esc(state.public.bank_instructions||'Hubungi admin untuk instruksi.')}</p>${p?.status==='AwaitingReview'?'<div class="inline-notice">Bukti sudah diterima. Tunggu pemeriksaan admin.</div>':form('proof',`<div class="field upload"><label for="proof-file">Bukti transfer (JPG, PNG, PDF)</label><input id="proof-file" type="file" name="file" accept="image/jpeg,image/png,application/pdf" required><p class="hint">Maksimal ${Math.floor(state.public.max_file_bytes/1048576)} MB. Akses aktif setelah admin menyetujui.</p></div>`,hidden('order_id',o.order_id),'Kirim Bukti Pembayaran')}`:`<p class="subtitle">Selesaikan pembayaran di halaman gateway, lalu periksa status di portal.</p><div class="gap">${isDemo?btn('Simulasikan Pembayaran Berhasil','demo-paid',`data-id="${esc(o.order_id)}"`):o.gateway_url?`<a class="btn block" href="${esc(o.gateway_url)}" target="_blank" rel="noopener noreferrer">Buka Halaman Pembayaran ↗</a>`:'<p class="hint">Tautan belum tersedia. Periksa status atau hubungi admin dengan nomor pesanan ini.</p>'}</div>`):'<p class="subtitle">Riwayat transaksi tersimpan pada akun Anda.</p>'}</aside></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">Belum ada data pada tampilan ini.</td></tr>`}</tbody></table></div>`;}
function renderTransactions(){main.innerHTML=head('Transaksi Saya','Riwayat pembelian dan status pembayaran.')+btn('Segarkan Transaksi','refresh-member','','secondary small')+`<div class="gap">`+table(['Pesanan / Kelas','Tanggal','Metode','Total','Status',''],state.member.orders.slice().reverse().map(o=>`<tr><td>${esc(o.title_snapshot)}<small>${esc(o.order_id)}</small></td><td>${date(o.created_at)}</td><td>${o.method==='manual'?'Manual':'Gateway'}</td><td>${money(o.total_idr)}</td><td>${badge(o.status)} ${orderPayments(o)?badge(orderPayments(o).status):''}</td><td>${link('Detail →','order/'+o.order_id,'btn small secondary')}</td></tr>`))+'</div>';}
function renderNotifications(){main.innerHTML=head('Notifikasi','Informasi terbaru untuk perjalanan belajarmu.')+`<section class="panel">${state.member.notifications.map(n=>`<div class="notice"><div class="notice-icon">✧</div><div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small class="hint">${date(n.created_at)}</small></div></div>`).join('')||empty('Belum ada notifikasi','Informasi kelas dan transaksi akan muncul di sini.')}</section>`;}
function renderProfile(){const u=state.user;main.innerHTML=head('Pengaturan Akun','Sesuaikan profil dan preferensi belajarmu.')+`<section class="panel" style="max-width:700px">${form('profile',field('name','Nama Lengkap',u.name,'text','required maxlength="100"')+field('wa_number','Nomor WhatsApp',u.wa_number,'tel','placeholder="08xxxxxxxxxx"')+`<div class="field"><label>Email Akun Google</label><input value="${esc(u.email)}" disabled></div>`+select('theme','Tema Tampilan',[['system','Ikuti Perangkat'],['light','Terang'],['dark','Gelap']],u.theme)+check('promo_consent','Saya bersedia menerima promosi kelas melalui WA/email.',u.promo_consent))}</section>`;}
function renderLogin(){main.innerHTML=`<section class="panel login-panel"><div class="login-mark">k.</div><div class="eyebrow">SELAMAT DATANG DI RUANG BELAJARMU</div><h1>Langkah kecil.<br>Kemungkinan besar.</h1><p>Masuk untuk mengakses kelas, melanjutkan pelajaran, dan mengembangkan karya digitalmu.</p><div id="google-login" class="gap"></div>${isDemo?`<div class="inline-notice gap">Demo lokal tersedia untuk mencoba alur member dan admin. Tidak ada transaksi uang atau pesan yang dikirim.</div><div class="row-actions">${btn('Coba sebagai Member','demo-role','data-value="Member"')}${btn('Coba sebagai Admin','demo-role','data-value="Admin"','secondary')}</div>`:''}<p class="hint gap">Gunakan akun Google yang sama saat membeli dan belajar.</p><a href="#catalog">Jelajahi kelas terlebih dahulu ↗</a></section>`;if(!isDemo)setupGoogle().catch(e=>$('#google-login')&&($('#google-login').textContent=e.message));}
async function setupGoogle(){if(!state.public.client_id)throw Error('Admin perlu mengatur GOOGLE_CLIENT_ID pada backend.');const challenge=await api('auth.challenge');if(!window.google){await new Promise((resolve,reject)=>{let s=$('#gsi-sdk');if(!s){s=document.createElement('script');s.id='gsi-sdk';s.src='https://accounts.google.com/gsi/client';s.async=true;document.head.append(s);}s.onload=resolve;s.onerror=()=>reject(Error('Tidak dapat memuat layanan login Google.'));});}if(!$('#google-login'))return;google.accounts.id.initialize({client_id:challenge.client_id,nonce:challenge.nonce,callback:async r=>{try{const auth=await api('auth.login',{credential:r.credential,nonce:challenge.nonce});setSession(auth.token,auth.user);state.user=auth.user;await refreshMember();applyTheme(state.user.theme||'system');location.hash='dashboard';}catch(e){toast(e.message,true);}}});google.accounts.id.renderButton($('#google-login'),{type:'standard',theme:'outline',size:'large',text:'signin_with',locale:'id'});}
function metrics(r){return `<div class="metric-grid">${[['Penerimaan Bruto',money(r.gross),'Pembayaran terverifikasi'],['Pengembalian Dana',money(r.refund),'Refund tercatat'],['Penerimaan Netto',money(r.net),'Bruto dikurangi refund'],['Member Aktif',r.active_members,'Belajar dalam 7 hari terakhir']].map(([label,value,hint])=>`<section class="panel metric"><span>${label}</span><strong>${value}</strong><small>${hint}</small></section>`).join('')}</div>`;}
function renderAdmin(){const r=state.report;main.innerHTML=head('Ringkasan Bisnis','Kelola kelas dan pelanggan dari satu tempat.',link('+ Buat Kelas','editor'))+metrics(r)+`<div class="two-col"><section class="panel"><div class="section-head"><h2>Performa Kelas</h2><a href="#reports">Laporan lengkap ↗</a></div>${chart(r.orders)}<p class="report-caption">Jumlah pesanan lunas per kelas. ${isDemo?'Seluruh angka adalah data simulasi.':''}</p></section><aside class="stack"><section class="panel"><h2>Perlu Ditindaklanjuti</h2><div class="status-row"><a href="#payments">Verifikasi pembayaran</a><b>${state.admin.payments.filter(p=>p.status==='AwaitingReview').length}</b></div><div class="status-row"><a href="#crm">Kontak CRM</a><b>${state.admin.totals.contacts}</b></div><div class="status-row"><a href="#messages">Pesan perlu diperiksa</a><b>${state.admin.queue.filter(q=>['Failed','Uncertain'].includes(q.status)).length}</b></div></section><section class="panel"><h3>Pengelolaan yang terarah</h3><p class="subtitle">Publikasikan kelas, periksa pembayaran, lalu pantau aktivitas belajar member.</p></section></aside></div>`;}
function chart(orders){const data=(state.admin?.courses||state.public.courses).map(c=>({name:c.title,value:orders.filter(o=>o.course_id===c.course_id&&o.status==='Paid').length}));const max=Math.max(1,...data.map(x=>x.value));return `<div class="chart" role="img" aria-label="Jumlah pesanan lunas: ${esc(data.map(x=>x.name+' '+x.value).join(', '))}">${data.map((x,i)=>`<div class="bar-wrap"><b>${x.value}</b><div class="bar" style="height:${x.value/max*100}%"></div><small>Kelas ${i+1}</small></div>`).join('')}</div><div class="report-caption">${data.map((x,i)=>`${i+1}. ${esc(x.name)}`).join('<br>')}</div>`;}
function pageButtons(total){return `<div class="pagination">${btn('←','admin-page',`data-value="${Math.max(0,state.page-1)}" ${state.page===0?'disabled':''}`,'small secondary')}<span>Halaman ${state.page+1} · ${total} data</span>${btn('→','admin-page',`data-value="${state.page+1}" ${(state.page+1)*50>=total?'disabled':''}`,'small secondary')}</div>`;}
function renderEditor(){main.innerHTML=head('Kelas & Materi','Susun pengetahuan menjadi perjalanan belajar yang terarah.',btn('+ Buat Kelas','edit-course'))+table(['Kelas','Kategori','Harga','Status',''],state.admin.courses.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(c.category)}</td><td>${money(c.price_idr)}</td><td>${badge(c.status)}</td><td><div class="row-actions">${btn('Edit','edit-course',`data-id="${esc(c.course_id)}"`,'small secondary')}${btn('Kurikulum','curriculum',`data-id="${esc(c.course_id)}"`,'small')}${link('Pratinjau ↗','course/'+c.course_id,'btn small ghost')}</div></td></tr>`));}
function editCourse(id){const c=state.admin.courses.find(c=>c.course_id===id)||{};showModal(id?'Edit Kelas':'Buat Kelas Baru',form('course',field('title','Judul Kelas',c.title,'text','required maxlength="160"')+field('description','Deskripsi',c.description,'textarea','required')+`<div class="form-grid">`+field('category','Kategori',c.category)+field('price_idr','Harga (Rupiah)',c.price_idr||99000,'number','required min="1" step="1"')+select('cover','Ilustrasi Sampul',[['code','Website & Kode'],['marketing','Marketing'],['design','Desain'],['business','Bisnis']],c.cover||'code')+select('status','Status',[['Draft','Draf'],['Published','Terbit'],['Archived','Arsip']],c.status||'Draft')+field('access_days','Masa Akses (0 = tanpa kedaluwarsa)',c.access_days||0,'number','min="0" step="1"')+field('sort_order','Urutan',c.sort_order||0,'number','min="0" step="1"')+`</div>`+check('sequential_lock','Wajib menyelesaikan pelajaran secara berurutan',c.sequential_lock)+`<p class="hint">Mengarsipkan kelas menghentikan penjualan baru. Hak pembeli lama mengikuti kebijakan akses.</p>`,hidden('course_id',c.course_id||'')));}
async function editCurriculum(id){const d=await api('course.read',{course_id:id});state.course=d;showModal('Kurikulum · '+d.course.title,`<div class="row-actions">${btn('+ Modul','module-form',`data-id="${esc(id)}"`)}${btn('+ Pelajaran','lesson-form',`data-id="${esc(id)}"`,'secondary')}${btn('+ Materi','material-form',`data-id="${esc(id)}"`,'secondary')}</div><div class="gap">${d.modules.map(m=>`<section class="module"><div class="lesson-row"><strong>${esc(m.title)}</strong>${btn('Edit Modul','module-form',`data-id="${esc(id)}" data-module="${esc(m.module_id)}"`,'small ghost')}</div>${d.lessons.filter(l=>l.module_id===m.module_id).map(l=>`<div class="lesson-row"><span>${esc(l.title)} <small>${truth(l.is_preview)?'Pratinjau':''}</small></span>${btn('Edit','lesson-form',`data-id="${esc(id)}" data-lesson="${esc(l.lesson_id)}"`,'small ghost')}</div>`).join('')}</section>`).join('')||empty('Tambahkan modul pertama','Buat modul, lalu masukkan pelajaran dan materi.')}</div>`);}
function curriculumForm(kind,id,recordId){const d=state.course,old=(kind==='module'?d.modules:d.lessons).find(r=>(kind==='module'?r.module_id:r.lesson_id)===recordId)||{};showModal(kind==='module'?'Modul Kelas':'Pelajaran Kelas',form('curriculum',(kind==='lesson'?select('module_id','Modul',d.modules.map(m=>[m.module_id,m.title]),old.module_id):'')+field('title','Judul',old.title,'text','required')+field('sort_order','Urutan',old.sort_order||0,'number','min="0"')+(kind==='lesson'?field('description','Deskripsi / Petunjuk Belajar',old.description,'textarea')+field('video_url','Tautan YouTube',old.video_url,'url','placeholder="https://www.youtube.com/watch?v=…"')+check('is_preview','Buka sebagai pratinjau publik',old.is_preview):''),hidden('course_id',id)+hidden('kind',kind)+(kind==='module'?hidden('module_id',old.module_id||''):hidden('lesson_id',old.lesson_id||''))));}
function materialForm(id){const d=state.course;showModal('Tambah Materi Pendukung',form('material',select('lesson_id','Pelajaran',d.lessons.map(l=>[l.lesson_id,l.title]))+field('title','Nama Materi','','text','required')+field('external_url','Tautan eksternal (opsional)','','url')+`<div class="field upload"><label for="material-file">Atau unggah dokumen / ZIP</label><input id="material-file" name="file" type="file"><p class="hint">Maksimal ${Math.floor(state.public.max_file_bytes/1048576)} MB. Berkas tetap privat.</p></div>`,hidden('course_id',id)) );}
function renderMembers(){main.innerHTML=head('Member','Pantau akun dan hak akses belajar.')+table(['Member','Peran','Akses Kelas',''],state.admin.users.map(u=>`<tr><td>${esc(u.name)}<small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${state.admin.enrollments.filter(e=>e.user_id===u.user_id&&e.status==='Active').length} kelas</td><td>${btn('Detail','member-detail',`data-id="${esc(u.user_id)}"`,'small secondary')}</td></tr>`))+pageButtons(state.admin.totals.users);}
function memberDetail(id){const u=state.admin.users.find(u=>u.user_id===id);showModal('Detail Member',`<h3>${esc(u.name)}</h3><p class="subtitle">${esc(u.email)}</p><p class="hint">${esc(u.wa_number||'Nomor WA belum diisi')}</p><h3 class="gap">Kelas yang Diakses</h3>${state.admin.enrollments.filter(e=>e.user_id===id).map(e=>`<div class="status-row"><span>${esc(state.admin.courses.find(c=>c.course_id===e.course_id)?.title||e.course_id)}</span>${badge(e.status)}</div>`).join('')||'<p class="subtitle">Belum ada akses kelas pada halaman data ini.</p>'}${u.user_id!==state.user.user_id?`<div class="form-actions">${btn('Aktifkan Akun','user-status',`data-id="${esc(id)}" data-value="Active"`,'secondary')}${btn('Blokir Akun','user-status',`data-id="${esc(id)}" data-value="Blocked"`,'danger')}</div>`:''}`);}
function renderPayments(){main.innerHTML=head('Pesanan & Pembayaran','Periksa pembayaran manual dan pantau transaksi gateway.',btn('Segarkan','refresh-admin','','secondary'))+table(['Kelas / Pesanan','Metode','Total','Pesanan','Pembayaran',''],state.admin.orders.map(o=>{const p=state.admin.payments.find(p=>p.order_id===o.order_id);return `<tr><td>${esc(o.title_snapshot)}<small>${esc(o.order_id)}</small></td><td>${o.method==='manual'?'Manual':'Gateway'}</td><td>${money(o.total_idr)}</td><td>${badge(o.status)}</td><td>${badge(p?.status||'AwaitingPayment')}</td><td>${btn('Periksa','review-payment',`data-id="${esc(o.order_id)}"`,'small secondary')}</td></tr>`;}))+pageButtons(state.admin.totals.orders);}
function reviewPayment(id){const o=state.admin.orders.find(o=>o.order_id===id),p=state.admin.payments.find(p=>p.order_id===id);showModal('Pemeriksaan Pembayaran',`<h3>${esc(o.title_snapshot)}</h3><p class="price">${money(o.total_idr)}</p><p class="hint">${esc(o.order_id)} · ${esc(o.method)}</p>${badge(o.status)} ${badge(p?.status||'AwaitingPayment')}<div class="gap">${p?.has_proof?btn('Lihat / Unduh Bukti','proof-download',`data-id="${esc(id)}"`,'secondary'):''}</div>${o.method==='manual'&&p?.status==='AwaitingReview'?form('payment-review',`<div class="inline-notice gap">Cocokkan bukti dengan mutasi rekening sebenarnya sebelum menyetujui pembayaran.</div>`+select('decision','Keputusan',[['approve','Setujui — dana telah diterima'],['reject','Tolak bukti pembayaran']])+field('reason','Catatan / Alasan penolakan','','textarea')+check('confirmed','Saya telah memeriksa mutasi dan nominal pembayaran.',false),hidden('order_id',id),'Simpan Keputusan'):''}${o.status==='Paid'?form('refund',`<div class="inline-notice gap">Pencatatan ini tidak mengirim pengembalian uang. Selesaikan transfer/refund pada penyedia terlebih dahulu.</div>`+field('reason','Alasan pengembalian dana','','textarea','required')+check('revoke','Cabut akses kelas terkait',false),hidden('order_id',id),'Catat Refund'):''}`);}
function renderCRM(){const stages=['Prospek','Tertarik','Menunggu Pembayaran','Pelanggan','Pembelian Ulang'],contacts=state.admin.contacts.filter(c=>(c.name+' '+c.email+' '+c.tags).toLowerCase().includes(state.search.toLowerCase()));main.innerHTML=head('CRM Kontak','Bangun hubungan dari ketertarikan pertama hingga pembelian ulang.',btn('+ Tambah Kontak','edit-contact'))+`<div class="toolbar"><input id="crm-search" placeholder="Cari nama, email, atau tag…" value="${esc(state.search)}" aria-label="Cari kontak">${btn(state.crmBoard?'Tampilan Tabel':'Tampilan Pipeline','crm-toggle','','secondary small')}</div>`+(state.crmBoard?`<div class="pipeline">${stages.map(s=>`<div class="pipeline-col"><h3>${s} · ${contacts.filter(c=>c.lifecycle_stage===s).length}</h3>${contacts.filter(c=>c.lifecycle_stage===s).map(c=>`<article class="contact-card"><strong>${esc(c.name)}</strong><p>${esc(c.email)}</p><span class="tag">${esc(c.tags||c.source||'Portal')}</span><div class="gap">${btn('Detail','edit-contact',`data-id="${esc(c.contact_id)}"`,'small secondary')}</div></article>`).join('')}</div>`).join('')}</div>`:table(['Kontak','Tahap','Sumber / Tag',''],contacts.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.email)}</small></td><td><span class="tag blue">${esc(c.lifecycle_stage)}</span></td><td>${esc(c.source||'Admin')}<small>${esc(c.tags)}</small></td><td>${btn('Detail / Follow-up','edit-contact',`data-id="${esc(c.contact_id)}"`,'small secondary')}</td></tr>`)))+pageButtons(state.admin.totals.contacts);}
function editContact(id){const c=state.admin.contacts.find(c=>c.contact_id===id)||{};showModal(id?'Kontak & Follow-up':'Tambah Kontak',form('contact',`<div class="form-grid">`+field('name','Nama',c.name,'text','required')+field('email','Email',c.email,'email','required')+field('wa_number','Nomor WA',c.wa_number,'tel')+select('lifecycle_stage','Tahap',['Prospek','Tertarik','Menunggu Pembayaran','Pelanggan','Pembelian Ulang'],c.lifecycle_stage||'Prospek')+`</div>`+field('tags','Tag / Minat',c.tags)+field('notes','Catatan',c.notes,'textarea')+`<p class="hint">Persetujuan promosi dikelola oleh pemilik akun. Menambah kontak tidak berarti menyetujui promosi.</p>`,hidden('contact_id',c.contact_id||''))) ;if(id)$('#modal-body').insertAdjacentHTML('beforeend',`<hr style="border:0;border-top:1px solid var(--border);margin:25px 0"><h3>Jadwalkan Follow-up</h3>${form('activity',field('notes','Catatan tindak lanjut','','textarea','required')+field('followup_at','Jadwal','','datetime-local'),hidden('contact_id',id),'Tambah Follow-up')}<h3 class="gap">Riwayat Tindak Lanjut</h3>${state.admin.activities.filter(a=>a.contact_id===id).map(a=>`<div class="notice"><div><strong>${esc(a.notes)}</strong><p>${date(a.followup_at||a.created_at)} · ${esc(a.status)}</p>${a.status==='Open'?btn('Selesaikan','complete-activity',`data-id="${esc(a.activity_id)}" data-contact="${esc(id)}"`,'small secondary'):''}</div></div>`).join('')||'<p class="hint">Belum ada tindak lanjut.</p>'}`);}
