function renderReports(){const r=state.report;const datasets=reportDatasets(r);const selected=datasets[state.reportKind];main.innerHTML=head('Laporan Bisnis & Pembelajaran','Angka yang terukur untuk keputusan berikutnya.',`<div class="row-actions no-print">${btn('Excel ↓','export-xlsx','','secondary')}${btn('Cetak / PDF','print-report','','secondary')}</div>`)+`<div class="panel no-print" style="margin-bottom:22px">${form('report-filter',`<div class="form-grid">`+field('from','Dari Tanggal',state.reportFilter.from||'','date')+field('to','Sampai Tanggal',state.reportFilter.to||'','date')+select('status','Status Pesanan',[['','Semua Status'],...['Pending','Paid','Expired','Cancelled','Refunded']],state.reportFilter.status||'')+select('method','Metode',[['','Semua Metode'],['manual','Manual'],['gateway','Gateway']],state.reportFilter.method||'')+field('source','Sumber Kontak (laporan CRM)',state.reportFilter.source||'')+select('course_id','Kelas',[['','Semua Kelas'],...state.admin.courses.map(c=>[c.course_id,c.title])],state.reportFilter.course_id||'')+`</div>`,'','Terapkan Filter')}</div>`+metrics(r)+`<p class="report-caption">Periode: ${state.reportFilter.from||'Semua waktu'} sampai ${state.reportFilter.to||'hari ini'}. Member aktif: aktivitas progres 7 hari terakhir. Pembelajaran: cohort akses yang diberikan dalam periode. Konversi kontak: ${Math.round(r.conversion*100)}% dari ${r.contacts} kontak baru dalam periode.</p><section class="panel"><h2>Pesanan Lunas per Kelas</h2>${chart(r.orders)}</section><div class="section-head gap"><h2>Rincian Laporan</h2><select id="report-kind" aria-label="Jenis laporan">${Object.entries(datasets).map(([key,x])=>`<option value="${key}" ${state.reportKind===key?'selected':''}>${x.label}</option>`).join('')}</select></div>`+table(selected.headers,selected.rows.map(row=>'<tr>'+row.map(cell=>'<td>'+esc(cell)+'</td>').join('')+'</tr>'));}
function renderSettings(){const data=state.settings,get=k=>data.settings.find(x=>x.key===k)?.value||'';main.innerHTML=head('Pengaturan Admin','Identitas portal, pembayaran, kanal pesan, dan migrasi.')+`<div class="two-col"><section class="panel"><h2>Pengaturan Portal</h2>${form('settings',field('APP_NAME','Nama Aplikasi',get('APP_NAME'))+field('APP_URL','URL Frontend (GitHub Pages)',get('APP_URL'),'url')+field('BANK_INSTRUCTIONS','Instruksi Transfer / QRIS Manual',get('BANK_INSTRUCTIONS'),'textarea')+field('REFUND_POLICY','Kebijakan Refund',get('REFUND_POLICY'),'textarea')+check('wa','Aktifkan notifikasi WhatsApp',data.channels.wa)+check('email','Aktifkan notifikasi Email',data.channels.email))}</section><aside class="stack"><section class="panel"><h2>Status Integrasi</h2>${Object.entries(data.integrations).filter(([key])=>key!=='SESSION_SECRET').map(([key,v])=>`<div class="status-row"><small>${esc(key)}</small>${badge(v.configured?'Active':'Draft')}</div>`).join('')}<p class="hint gap">Rahasia tersimpan pada Script Properties. Nilai kosong pada form berikut tidak mengubah konfigurasi.</p>${form('secrets',field('FONNTE_TOKEN','Token WhatsApp','','password','autocomplete="new-password"')+field('MIDTRANS_SERVER_KEY','Server Key Gateway','','password','autocomplete="new-password"'))}</section><section class="panel"><h2>Migrasi Database</h2><p class="hint">Sumber hanya dibaca. Dry-run wajib sebelum impor. Pembayaran, akun, dan hak akses tidak ditimpa.</p>${form('migration',field('source_id','Spreadsheet ID sumber','','text','required'),'','Pindai / Dry-run')}</section></aside></div>`;}
async function fileData(file){if(!file)throw Error('Pilih berkas terlebih dahulu.');if(file.size>state.public.max_file_bytes)throw Error('Berkas melebihi batas '+Math.floor(state.public.max_file_bytes/1048576)+' MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({base64:String(reader.result).split(',')[1],name:file.name,mime:file.type||'application/octet-stream'});reader.onerror=()=>reject(Error('Berkas tidak dapat dibaca.'));reader.readAsDataURL(file);});}
function download(file){if(file.url){const u=new URL(file.url);if(u.protocol!=='https:')throw Error('Tautan tidak aman.');window.open(u.href,'_blank','noopener,noreferrer');return;}const bytes=Uint8Array.from(atob(file.base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:file.mime||'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=file.name||'materi';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function act(el){const action=el.dataset.action,id=el.dataset.id,v=el.dataset.value;switch(action){
 case 'retry':if(!state.public)return start();return route();case 'course-filter':state.filter=v;return renderDashboard();
 case 'demo-role':demoRole(v);await refreshMember();state.admin=null;location.hash=v==='Admin'?'admin':'dashboard';return route();
 case 'refresh-member':await refreshMember();return route();case 'refresh-admin':await refreshAdmin();return route();
 case 'admin-page':state.page=Number(v);await refreshAdmin();return route();
 case 'complete':{const detail=state.course;await api('progress.save',{lesson_id:id,completed:v==='true'});await refreshMember();detail.progress=state.member.progress;toast(v==='true'?'Pelajaran selesai. Progres tersimpan.':'Progres diperbarui.');return route();}
 case 'resource':return download(await api('resource.get',{material_id:id}));
 case 'refresh-payment':await api('payment.refresh',{order_id:id});await refreshMember();return route();
 case 'demo-paid':if(!isDemo)return;await api('demo.gateway.complete',{order_id:id});await refreshMember();toast('Simulasi pembayaran berhasil.');return route();
 case 'edit-course':return editCourse(id);case 'curriculum':return editCurriculum(id);case 'module-form':return curriculumForm('module',id,el.dataset.module);case 'lesson-form':return curriculumForm('lesson',id,el.dataset.lesson);case 'material-form':return materialForm(id);
 case 'member-detail':return memberDetail(id);case 'user-status':if(!confirm('Ubah status akun ini? Sesi akun akan dicabut.'))return;await api('admin.user.status',{user_id:id,status:v});await refreshAdmin();modal.close();toast('Status akun diperbarui.');return route();
 case 'review-payment':return reviewPayment(id);case 'proof-download':return download(await api('admin.payment.proof',{order_id:id}));
 case 'campaign':return campaignForm();case 'complete-activity':await api('admin.crm.complete',{activity_id:id});await refreshAdmin();return editContact(el.dataset.contact);case 'crm-toggle':state.crmBoard=!state.crmBoard;return renderCRM();case 'edit-contact':return editContact(id);case 'edit-template':return editTemplate(id);
 case 'retry-notification':if(!confirm('Periksa dashboard provider terlebih dahulu. Lanjutkan mengantrekan ulang pesan ini?'))return;await api('admin.notification.retry',{job_id:id,confirm:true});await refreshAdmin();toast('Pesan masuk antrean ulang.');return route();
 case 'export-xlsx':{const selected=reportDatasets(state.report)[state.reportKind];return downloadXlsx('Laporan_'+state.reportKind+'_Portal_Kelas_Digital.xlsx',[selected.headers,...selected.rows]);}
 case 'print-report':return window.print();
 }}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(el.disabled)return;const busy=el.textContent;el.disabled=true;try{await act(el);}catch(error){toast(error.message,true);}finally{if(el.isConnected){el.disabled=false;el.textContent=busy;}}});
document.addEventListener('change',e=>{if(e.target.id==='report-kind'){state.reportKind=e.target.value;renderReports();}});
let requestKeys={};
document.addEventListener('submit',async event=>{const f=event.target.closest('form[data-form]');if(!f)return;event.preventDefault();const type=f.dataset.form,fd=new FormData(f),d=Object.fromEntries(fd),submit=f.querySelector('[type=submit]'),label=submit.textContent;const status=f.querySelector('.form-status');submit.disabled=true;submit.textContent='Memproses…';status.textContent='';try{
 switch(type){
 case 'campaign-plan':{const plan=await api('admin.campaign.plan',d);showModal('Tinjau Promosi',`<div class="inline-notice">${plan.count} penerima aktif sesuai segmen dan persetujuan promosi. Pesan masuk antrean; pengiriman mengikuti status kanal.</div><p class="body-copy">${esc(d.body)}</p>${form('campaign-send',check('confirmed','Saya menyetujui isi pesan dan penerima ini.',false),Object.entries({...d,fingerprint:plan.fingerprint,request_key:crypto.randomUUID()}).map(([k,v])=>hidden(k,v)).join(''),'Masukkan ke Antrean')}`);break;}
 case 'campaign-send':{if(!fd.has('confirmed'))throw Error('Konfirmasi pesan terlebih dahulu.');const r=await api('admin.campaign.send',{...d,confirm:true});await refreshAdmin();modal.close();toast(r.queued+' pesan masuk antrean promosi.');await route();break;}
 case 'profile':{state.user=await api('profile.save',{...d,promo_consent:fd.has('promo_consent')});state.member.user=state.user;applyTheme(state.user.theme);nav();toast('Profil tersimpan.');break;}
 case 'checkout':{const k=d.course_id+':'+d.method;requestKeys[k] ||= crypto.randomUUID();const o=await api('order.create',{...d,request_key:requestKeys[k]});await refreshMember();location.hash='order/'+o.order_id;break;}
 case 'proof':await api('file.upload',{kind:'proof',order_id:d.order_id,...await fileData(fd.get('file'))});await refreshMember();toast('Bukti diterima. Menunggu pemeriksaan admin.');await route();break;
 case 'course':{const c=await api('admin.course.save',{...d,sequential_lock:fd.has('sequential_lock'),price_idr:Number(d.price_idr),access_days:Number(d.access_days),sort_order:Number(d.sort_order)});await refreshAdmin();state.public=await publicBoot();modal.close();toast('Kelas tersimpan.');await route();break;}
 case 'curriculum':{await api('admin.curriculum.save',{...d,sort_order:Number(d.sort_order),is_preview:fd.has('is_preview')});await refreshAdmin();await editCurriculum(d.course_id);toast('Kurikulum tersimpan.');break;}
 case 'material':{let uploaded={};const file=fd.get('file');if(file?.size)uploaded=await api('file.upload',{kind:'material',...await fileData(file)});if(!uploaded.file_id&&!d.external_url)throw Error('Pilih berkas atau isi tautan.');await api('admin.material.save',{...d,...uploaded});await editCurriculum(d.course_id);toast('Materi ditambahkan.');break;}
 case 'payment-review':{if(d.decision==='approve'&&!fd.has('confirmed'))throw Error('Konfirmasi pemeriksaan mutasi terlebih dahulu.');if(d.decision==='reject'&&!d.reason.trim())throw Error('Alasan penolakan wajib diisi.');await api('admin.payment.review',{order_id:d.order_id,approve:d.decision==='approve',reason:d.reason});await refreshAdmin();modal.close();toast('Keputusan pembayaran tersimpan.');await route();break;}
 case 'refund':if(!confirm('Dana sudah dikembalikan melalui bank/gateway? Catat refund sekarang?'))return;await api('admin.refund.record',{...d,revoke:fd.has('revoke')});await refreshAdmin();modal.close();toast('Refund dicatat.');await route();break;
 case 'contact':await api('admin.crm.save',d);await refreshAdmin();modal.close();toast('Kontak tersimpan.');await route();break;
 case 'activity':await api('admin.crm.activity',d);await refreshAdmin();editContact(d.contact_id);toast('Follow-up ditambahkan.');break;
 case 'template':await api('admin.template.save',{...d,enabled:fd.has('enabled'),promotional:fd.has('promotional')});await refreshAdmin();modal.close();toast('Template tersimpan.');await route();break;
 case 'report-filter':if(d.from&&d.to&&d.to<d.from)throw Error('Tanggal akhir harus setelah atau sama dengan tanggal awal.');state.reportFilter=d;await route();break;
 case 'settings':{const {wa,email,...settings}=d;await api('admin.settings.save',{settings,channels:{wa:fd.has('wa'),email:fd.has('email')}});state.public=await publicBoot();toast('Pengaturan tersimpan.');await route();break;}
 case 'secrets':await api('admin.secrets.save',d);f.reset();toast('Konfigurasi integrasi diperbarui.');await route();break;
 case 'migration':{const result=await api('admin.migration.plan',d);showModal('Hasil Dry-run Migrasi',`<div class="inline-notice">Belum ada data yang ditulis. Periksa hasil rencana berikut.</div>${table(['Tabel','Tambah','Ubah','Lewati'],Object.entries(result.tables).map(([name,s])=>`<tr><td>${esc(name)}</td><td>${s.inserted}</td><td>${s.updated}</td><td>${s.skipped}</td></tr>`))}${form('migration-apply',check('confirmed','Saya telah membuat backup target dan menyetujui rencana ini.',false),hidden('source_id',d.source_id)+hidden('fingerprint',result.fingerprint),'Jalankan Migrasi')}`);break;}
 case 'migration-apply':if(!fd.has('confirmed'))throw Error('Konfirmasi backup dan rencana migrasi diperlukan.');await api('admin.migration.apply',d);await refreshAdmin();modal.close();toast('Migrasi selesai. Sumber tidak diubah.');await route();break;
 }
 }catch(error){status.textContent=error.message;}finally{if(submit.isConnected){submit.disabled=false;submit.textContent=label;}}
});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='course-search'){state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(paintCatalog,150);}if(e.target.id==='crm-search'){state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(location.hash!=='#crm'||!state.admin)return;const pos=e.target.selectionStart;renderCRM();const input=$('#crm-search');input.focus();input.setSelectionRange(pos,pos);},180);}});
