function connection(){const el=$('#connection');el.innerHTML=`<i style="background:${navigator.onLine?'#51b794':'#d79b47'}"></i>${navigator.onLine?'Online':'Offline'}`;if(!navigator.onLine)toast('Anda offline. Transaksi dan sinkronisasi memerlukan internet.',true);}window.addEventListener('online',connection);window.addEventListener('offline',connection);
