async function start(){main.innerHTML='<div class="skeleton title"></div><div class="skeleton"></div><div class="skeleton"></div>';try{state.public=await publicBoot();if(isDemo){$('#demo-banner').hidden=false;$('#demo-banner').insertAdjacentHTML('beforeend',' · <button data-action="demo-role" data-value="Member">Demo Member</button> <button data-action="demo-role" data-value="Admin">Demo Admin</button>');await refreshMember();}nav();if(!location.hash)location.hash=isDemo?'dashboard':'catalog';else await route();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Mode offline belum tersedia pada browser ini.'));}catch(e){main.innerHTML=head('Portal belum terhubung','Periksa konfigurasi backend.')+empty('Tidak dapat memuat portal',e.message)+btn('Coba Lagi','retry');nav();}}
