function reportDatasets(r){return {
 sales:{label:'Penjualan & Pembayaran',headers:['Tanggal','Kelas','Nominal IDR','Metode','Status'],rows:r.orders.map(o=>[date(o.created_at),o.title_snapshot,Number(o.total_idr),o.method,o.status])},
 revenue:{label:'Pendapatan',headers:['Metrik','IDR'],rows:[['Penerimaan Bruto',r.gross],['Refund',r.refund],['Penerimaan Netto',r.net]]},
 crm:{label:'CRM & Konversi',headers:['Nama','Email','Sumber','Tahap'],rows:(r.report_contacts||[]).map(c=>[c.name,c.email,c.source,c.stage])},
 learning:{label:'Member & Pembelajaran',headers:['Member','Kelas','Akses','Selesai','Total','Progres %','Aktivitas Terakhir'],rows:(r.learning||[]).map(l=>[l.name,l.course,l.status,l.completed,l.total,l.total?Math.round(l.completed/l.total*100):0,date(l.last_activity)])},
 notifications:{label:'Notifikasi',headers:['Kanal / Status','Jumlah'],rows:Object.entries(r.notification_summary||{})}
};}

function campaignForm(){showModal('Promosi Berbasis Persetujuan',form('campaign-plan',select('channel','Kanal',[['EMAIL','Email'],['WA','WhatsApp']],'EMAIL')+select('stage','Tahap Kontak',[['','Semua Tahap'],'Prospek','Tertarik','Menunggu Pembayaran','Pelanggan','Pembelian Ulang'],'')+field('tag','Tag / Minat (opsional)')+field('subject','Subjek Email')+field('body','Pesan (gunakan {name} untuk nama)','','textarea','required')+'<p class="hint">Hanya akun aktif dengan persetujuan promosi dan tujuan valid yang disertakan. Kontak manual tanpa akun tidak dikirimi promosi. Maksimal 200 penerima per kampanye.</p>','','Tinjau Penerima'));}

function eventLabel(event){return ({'account.created':'Akun baru','order.created':'Pesanan baru','payment.review':'Bukti menunggu review','access.granted':'Akses kelas aktif','payment.rejected':'Bukti ditolak','learning.reminder':'Pengingat belajar','material.published':'Materi baru'})[event]||event;}
